<script>document.addEventListener('DOMContentLoaded',()=>{
// Evita el "salto" (scroll al inicio) cuando un checkbox/switch del constructor
// recibe foco: se preserva la posición de scroll del contenedor desplazable.
(function(){
  var sc = document.querySelector('[data-design-scroll-container]');
  document.querySelectorAll('.home-builder input[type=checkbox],.home-builder input[type=radio]').forEach(function(inp){
    inp.addEventListener('mousedown', function(){
      var top = sc ? sc.scrollTop : window.scrollY;
      requestAnimationFrame(function(){ if(sc){ sc.scrollTop = top; } else { window.scrollTo(0, top); } });
    });
  });
})();
const list=document.querySelector('[data-section-list]');if(!list)return;let dragged;const sync=()=>{const wrap=document.querySelector('[data-order-inputs]');wrap.innerHTML='';list.querySelectorAll('.hb-section').forEach((card,i)=>{const input=document.createElement('input');input.type='hidden';input.name='order[]';input.value=card.dataset.component;wrap.appendChild(input);const order=card.querySelector('input[name=sort_order]');if(order)order.value=(i+1)*10})};list.querySelectorAll('.hb-section').forEach(card=>{const handle=card.querySelector('.hb-drag');if(handle){handle.addEventListener('dragstart',e=>{if(innerWidth<901){e.preventDefault();return}dragged=card;card.classList.add('is-dragging')});handle.addEventListener('dragend',()=>{card.classList.remove('is-dragging');dragged=null;sync()})}card.addEventListener('dragover',e=>{if(!dragged)return;e.preventDefault();if(card!==dragged)card.classList.add('drag-over')});card.addEventListener('dragleave',()=>card.classList.remove('drag-over'));card.addEventListener('drop',e=>{if(!dragged)return;e.preventDefault();card.classList.remove('drag-over');if(dragged===card)return;const r=card.getBoundingClientRect();list.insertBefore(dragged,e.clientY<r.top+r.height/2?card:card.nextSibling);sync()})})});</script>
